import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"LINE","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/line.md","filePath":"zh/integrations/channels/line.md","lastUpdated":1790952322000}'),s={name:"zh/integrations/channels/line.md"};function l(r,e,i,h,g,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="line" tabindex="-1">LINE <a class="header-anchor" href="#line" aria-label="Permalink to &quot;LINE&quot;">​</a></h1><p>把 Memoh Bot 接入 LINE 官方账号:用户加该账号为好友,即可与 Bot 1 对 1 聊天。</p><div class="warning custom-block"><p class="custom-block-title">使用限制</p><ul><li>仅支持私聊。群和多人聊天室的消息会被忽略,把 Bot 拉进 LINE 群没有用。</li><li>仅输出纯文本,不渲染 Markdown。</li><li>出站媒体仅限 PNG/JPEG 图片。图片必须公网 HTTPS 可访问,且符合 LINE 体积限制(原图 10 MB、预览图 1 MB);图片之外的附件发不出去。</li><li>入站的语音、视频、贴图、位置不处理。入站图片必须由 LINE 托管(在 App 里直接发照片就是这种)。</li><li>无流式输出,回复整条送达;超长回复按 LINE 的 5000 字符上限拆成多条。</li><li>回复走 LINE <strong>Push API</strong>,计入 LINE 套餐的推送条数配额。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>LINE 用 <strong>webhook</strong> 推消息进来,出站图片也由 LINE 服务器来抓取,所以 Memoh 部署必须有公网 HTTPS 入口,二选一:</p><ul><li>设 <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> 为公网 HTTPS origin(不能带路径、端口、内网地址);</li><li>或在 server deploy 里启用 Cloudflare Quick Tunnel profile,Memoh 会自动拿到公网地址。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-line-developers-console-创建-messaging-api-channel" tabindex="-1">1. 在 LINE Developers Console 创建 Messaging API channel <a class="header-anchor" href="#_1-在-line-developers-console-创建-messaging-api-channel" aria-label="Permalink to &quot;1. 在 LINE Developers Console 创建 Messaging API channel&quot;">​</a></h3><p>在 LINE Developers Console:</p><ol><li>打开 <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>。</li><li>建(或选)一个 provider,在下面创建 <strong>Messaging API</strong> channel,它会关联一个 LINE 官方账号。</li><li>在 <strong>Basic settings</strong> 里复制 <strong>Channel secret</strong>。</li><li>在 <strong>Messaging API</strong> tab 里签发并复制 <strong>Channel access token</strong>(长效)。</li></ol><blockquote><p>官方文档:<a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">Messaging API - Getting Started</a></p></blockquote><h3 id="_2-在-memoh-里添加渠道" tabindex="-1">2. 在 Memoh 里添加渠道 <a class="header-anchor" href="#_2-在-memoh-里添加渠道" aria-label="Permalink to &quot;2. 在 Memoh 里添加渠道&quot;">​</a></h3><p>在 Memoh:</p><ol><li>打开 Bot 的 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>,选择 <strong>LINE</strong>。</li><li>贴入 <strong>Channel Secret</strong> 和 <strong>Channel Access Token</strong>。</li><li>点 <strong>Save</strong>(或 <strong>Save and Enable</strong>)。回调 URL 要保存之后才会生成。</li></ol><h3 id="_3-注册-webhook" tabindex="-1">3. 注册 webhook <a class="header-anchor" href="#_3-注册-webhook" aria-label="Permalink to &quot;3. 注册 webhook&quot;">​</a></h3><p>在 Memoh,保存后面板会显示只读的 <strong>WebHook Callback URL</strong>,格式:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;公网 base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>两种注册方式:</p><ul><li>点 <strong>Set in LINE</strong>——Memoh 直接通过 Messaging API 把地址写进 LINE channel。有未保存的改动会先报错,保存了再点。</li><li>或点 <strong>Copy</strong>,到 LINE Developers Console 的 <strong>Messaging API → Webhook URL</strong> 手动粘贴。</li></ul><p>最后在 LINE Developers Console 里确认该 channel 的 <strong>Use webhook</strong> 已打开。</p><p>Memoh 会用 <strong>Channel Secret</strong> 校验入站 webhook 的签名,事件在 24 小时内去重。</p><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><strong>Channel Secret</strong></td><td>是</td><td>在 Messaging API channel 的 <strong>Basic settings</strong> 里复制。</td></tr><tr><td><strong>Channel Access Token</strong></td><td>是</td><td>在 <strong>Messaging API</strong> tab 里签发的长效 token。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>用 LINE 加该官方账号为好友,在 1 对 1 聊天中给 Bot 发送 <code>/help</code>。Bot 回复命令列表,说明渠道已接通。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>随时可在 Bot 的 <strong>平台</strong> 标签页停用或移除该渠道。更换凭据时,在同一面板更新 <strong>Channel Secret</strong> / <strong>Channel Access Token</strong> 并保存即可。</p><h2 id="faq" tabindex="-1">常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题 {#faq}&quot;">​</a></h2><h3 id="no-public-base-url" tabindex="-1">面板提示拿不到公网 base URL <a class="header-anchor" href="#no-public-base-url" aria-label="Permalink to &quot;面板提示拿不到公网 base URL {#no-public-base-url}&quot;">​</a></h3><p>没有公网 HTTPS origin 就生成不了 webhook 回调 URL。先按前提条件把 <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> 或 Cloudflare Quick Tunnel 配好。</p>',30)])])}const b=o(s,[["render",l]]);export{p as __pageData,b as default};
